export const NAVIGATION_FEATURE_COUNT=520;
export const navigationSnapshot=(state={})=>{const p=state.navigationProgress||{};const verified=Object.values(p).filter(v=>v==="verified").length;const building=Object.values(p).filter(v=>v==="building").length;return {total:NAVIGATION_FEATURE_COUNT,verified,building,pending:NAVIGATION_FEATURE_COUNT-verified-building};};
export const setNavigationFeatureState=(state,id,status)=>({...state,navigationProgress:{...(state.navigationProgress||{}),[id]:status}});
const norm=v=>String(v??"").toLowerCase().replace(/[.,!?;:()[\]{}]/g," ").replace(/\s+/g," ").trim();
const first=(s,re)=>{const m=s.match(re);return m?m[1]||m[0]:null};
export function navigationIntent(message,state={}){
 const x=norm(message), n={message,action:"open",destination:null,video:/\b(video|watch|lesson|tutorial|lecture)\b/.test(x),
 grade:first(x,/\b(?:grade|class|year|form|standard)\s*(?:12|twelve|11|eleven|10|ten|9|nine)\b/),
 chapter:first(x,/\b(?:chapter|ch)\s*(\d+)\b/),unit:first(x,/\b(?:unit)\s*(\d+)\b/),
 subject:null,topic:null,query:x};
 if(/\b(?:futurex|future x)\b/.test(x)) n.destination="futurex";
 else if(/\b(?:youtube|you tube)\b/.test(x)) n.destination="youtube";
 else if(/\b(?:browser|web|website|google|internet)\b/.test(x)) n.destination="web";
 const subjects=["math","mathematics","physics","chemistry","biology","agriculture","english","it","information technology","web design"];
 for(const s of subjects)if(x.includes(s)){n.subject=s;break}
 const tm=x.match(/\b(?:about|on|for|topic)\s+(.+?)(?:\s+on\s+(?:futurex|youtube))?$/); if(tm)n.topic=tm[1].trim();
 if(/\b(?:search|find|look for)\b/.test(x))n.action="search";
 if(/\b(?:play|watch)\b/.test(x))n.action="play";
 if(/\b(?:open|launch|show|take me|go to)\b/.test(x))n.action="open";
 if(/\b(?:related|recommended|next|current|weakest)\b/.test(x))n.contextual=true;
 return n;
}
export function buildNavigationTarget(intent,state={}){
 const q=[intent.grade,intent.subject,intent.chapter&&("chapter "+intent.chapter),intent.unit&&("unit "+intent.unit),intent.topic].filter(Boolean).join(" ");
 const query=(q||intent.query).trim();
 if(intent.destination==="youtube")return {type:"external",destination:"youtube",url:"https://www.youtube.com/results?search_query="+encodeURIComponent(query),query};
 if(intent.destination==="web")return {type:"external",destination:"web",url:"https://www.google.com/search?q="+encodeURIComponent(query),query};
 if(intent.destination==="futurex")return {type:"app",destination:"futurex",packageName:"com.inspireethiopia.net.futurexappversion2",query,deepLink:null,deepLinkVerified:false,fallback:"launch-app-or-search"};
 return {type:intent.video?"external":"search",destination:intent.video?"youtube":"web",url:"https://www.youtube.com/results?search_query="+encodeURIComponent(query),query};
}
export function navigationDecision(intent){
 if(!intent.message?.trim())return {allowed:false,reason:"empty"};
 if(intent.destination==="futurex"&&!intent.subject&&!intent.chapter&&!intent.topic&&!intent.grade)return {allowed:true,needsContext:true};
 return {allowed:true,needsContext:false};
}
export function navigationContext(state={}){
 return {grade:state.grade||state.profile?.grade||12,subjects:state.subjects||[],active:state.active||null,mastery:state.mastery||{},plans:state.plans||[],lastNavigation:state.lastNavigation||null};
}
export function resolveNavigation(message,state={}){
 const context=navigationContext(state), intent=navigationIntent(message,state);
 if(intent.contextual){
   if(!intent.subject&&context.active?.subject)intent.subject=context.active.subject;
   if(!intent.topic&&context.active?.topic)intent.topic=context.active.topic;
 }
 const decision=navigationDecision(intent);
 return {intent,decision,target:buildNavigationTarget(intent,{...state,...context})};
}
export function recordNavigation(state,target,result="requested"){
 return {...state,lastNavigation:{target,result,time:Date.now()},navigationHistory:[...(state.navigationHistory||[]),{target,result,time:Date.now()}].slice(-50)};
}
